// Only react to "hi"-style words from YOUR chat. Edit TRIGGER to change the words.
const TRIGGER = /^\s*(hi|hello|hey|\/start|update|\/update)\s*[.!]*\s*$/i;
const m = $json.message;
const ok = m && m.text && String(m.chat.id) === String($env.TELEGRAM_CHAT_ID) && TRIGGER.test(m.text);
return ok ? [{ json: { text: m.text } }] : [];

// Collect NSE session cookies from the first call and fan out to the two indices.
const sc = $input.first().json.headers?.['set-cookie'] || [];
const cookie = (Array.isArray(sc) ? sc : [sc]).map(c => c.split(';')[0]).join('; ');
// Add/remove NSE index symbols here (e.g. 'FINNIFTY', 'MIDCPNIFTY').
return ['NIFTY', 'BANKNIFTY'].map(symbol => ({ json: { symbol, cookie } }));

const symbols = $('Prepare Requests').all().map(i => i.json.symbol);
const chains  = $('NSE Option Chain').all().map(i => i.json);
const fmt = n => Number(n).toLocaleString('en-IN');
const sgn = n => (n > 0 ? '+' : '') + fmt(n);
const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false });
const out = [`📊 <b>India Market Update</b> — ${now} IST`];

chains.forEach((c, i) => {
  const name = symbols[i];
  const rec = c && c.records;
  if (!rec || !rec.data || !rec.data.length) {
    out.push(`\n<b>${name}</b>: NSE data unavailable (request blocked or session expired)`);
    return;
  }
  const expiry = rec.expiryDates[0];                       // nearest expiry
  const rows = rec.data.filter(r => r.expiryDate === expiry);
  let ceOI = 0, peOI = 0, ceChg = 0, peChg = 0;
  let maxCE = { oi: 0, strike: 0 }, maxPE = { oi: 0, strike: 0 };
  for (const r of rows) {
    if (r.CE) {
      ceOI += r.CE.openInterest || 0; ceChg += r.CE.changeinOpenInterest || 0;
      if ((r.CE.openInterest || 0) > maxCE.oi) maxCE = { oi: r.CE.openInterest, strike: r.strikePrice };
    }
    if (r.PE) {
      peOI += r.PE.openInterest || 0; peChg += r.PE.changeinOpenInterest || 0;
      if ((r.PE.openInterest || 0) > maxPE.oi) maxPE = { oi: r.PE.openInterest, strike: r.strikePrice };
    }
  }
  const pcr = ceOI ? (peOI / ceOI).toFixed(2) : 'n/a';
  out.push(
`\n<b>${name}</b>  ${fmt(rec.underlyingValue)}  (expiry ${expiry})
Call OI ${fmt(ceOI)} (${sgn(ceChg)}) | Put OI ${fmt(peOI)} (${sgn(peChg)})
PCR ${pcr} | Max Call OI (resistance) ${maxCE.strike} | Max Put OI (support) ${maxPE.strike}`);
});

// Sensex: index level only (BSE has no free public OI feed)
const m = $input.first().json?.chart?.result?.[0]?.meta;
if (m && m.regularMarketPrice) {
  const prev = m.chartPreviousClose ?? m.previousClose;
  const ch = prev ? m.regularMarketPrice - prev : 0;
  const pct = prev ? (ch / prev * 100).toFixed(2) : '0.00';
  out.push(`\n<b>SENSEX</b>  ${fmt(m.regularMarketPrice)}  (${ch >= 0 ? '+' : ''}${ch.toFixed(2)}, ${pct}%)\nOI: not available from a free public source`);
} else {
  out.push(`\n<b>SENSEX</b>: quote unavailable`);
}
return [{ json: { text: out.join('\n') } }];

// Add or remove RSS feeds here. Region is derived from the article domain in 'Format Message'.
const feeds = [
  { url: 'https://search.cnbc.com/rs/search/combinedcms/view.xml?partnerId=wrss01&id=10000664' }, // US
  { url: 'https://finance.yahoo.com/news/rssindex' },                                              // US
  { url: 'https://feeds.bbci.co.uk/news/business/rss.xml' },                                       // London
  { url: 'https://www.theguardian.com/business/rss' },                                             // London
  { url: 'https://asia.nikkei.com/rss/feed/nar' },                                                 // Asia
  { url: 'https://www.straitstimes.com/news/business/rss.xml' },                                   // Asia
];
return feeds.map(f => ({ json: f }));

// domain suffix -> region. Extend this map when you add feeds.
const MAP = {
  'cnbc.com': 'US', 'yahoo.com': 'US',
  'bbc.co.uk': 'LONDON', 'bbc.com': 'LONDON', 'theguardian.com': 'LONDON',
  'nikkei.com': 'ASIA', 'straitstimes.com': 'ASIA',
};
const regionOf = link => {
  try { const h = new URL(link).hostname; for (const k in MAP) if (h.endsWith(k)) return MAP[k]; } catch (e) {}
  return 'OTHER';
};
const HOURS = Number($env.NEWS_LOOKBACK_HOURS || 3.25);   // look-back window; set NEWS_LOOKBACK_HOURS=8 for 4 runs/day
const cutoff = Date.now() - HOURS * 3600 * 1000;
const PER_REGION = 4;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const buckets = { US: [], LONDON: [], ASIA: [], OTHER: [] };
const seen = new Set();
for (const it of $input.all()) {
  const j = it.json;
  if (!j.title || !j.link || seen.has(j.link)) continue;   // skips failed feeds too
  seen.add(j.link);
  const t = Date.parse(j.isoDate || j.pubDate || '');
  if (!isNaN(t) && t < cutoff) continue;                   // too old
  buckets[regionOf(j.link)].push({ title: j.title, link: j.link, t: isNaN(t) ? 0 : t });
}
const heads = { US: '🇺🇸 <b>US</b>', LONDON: '🇬🇧 <b>London / Europe</b>', ASIA: '🌏 <b>Asia</b>' };
const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false });
let text = `🌍 <b>Global Markets News</b> — ${now} IST`;
for (const r of ['US', 'LONDON', 'ASIA']) {
  const list = buckets[r].sort((a, b) => b.t - a.t).slice(0, PER_REGION);
  text += `\n\n${heads[r]}\n` + (list.length
    ? list.map(x => `• <a href="${esc(x.link)}">${esc(x.title)}</a>`).join('\n')
    : '• no new headlines in this window');
}
return [{ json: { text } }];
